export const motorbikes = vehicles.filter((v) => v.category === "motorbike");
export const cars = vehicles.filter((v) => v.category === "auto");
export const bicycles = vehicles.filter((v) => v.category === "bicycle");

export const bySlug = (slug: string) => vehicles.find((v) => v.slug === slug);

/**
 * Real cost of a rental of `days` days, using the published ladder.
 * Monthly tariffs are priced as a whole period, not days x rate — this mirrors
 * the wording on /ru/pricing/ ("на 30, 60 и 90 дней мы считаем стоимость целого периода").
 */
export function quote(v: Pick<Vehicle, "prices">, days: number): { total: number; perDay: number; tier: string } | null {
  const p = v.prices;
  if (days >= 90 && p.month3) { const total = p.month3 * 3; return { total, perDay: Math.round(total / 90), tier: "3 месяца" }; }
  if (days >= 60 && p.month2) { const total = p.month2 * 2; return { total, perDay: Math.round(total / 60), tier: "2 месяца" }; }
  if (days >= 30 && p.month1) { const total = p.month1; return { total, perDay: Math.round(total / 30), tier: "1 месяц" }; }
  if (days >= 7 && p.day7) { const total = p.day7 * days; return { total, perDay: p.day7, tier: "от 7 дней" }; }
  if (days >= 3 && p.day3) { const total = p.day3 * days; return { total, perDay: p.day3, tier: "от 3 дней" }; }
  if (p.day1) return { total: p.day1 * days, perDay: p.day1, tier: "посуточно" };
  if (p.day3) { const total = p.day3 * days; return { total, perDay: p.day3, tier: "от 3 дней (мин. срок)" }; }
  return null;
}

/** The lowest honest per-day figure and the duration you must book to reach it. */
export function cheapestPerDay(v: Pick<Vehicle, "prices">): { perDay: number; days: number } | null {
  const q = [30, 60, 90, 7, 3, 1].map((d) => ({ d, q: quote(v, d) })).filter((x) => x.q);
  if (!q.length) return null;
  const best = q.reduce((a, b) => (a.q!.perDay <= b.q!.perDay ? a : b));
  return { perDay: best.q!.perDay, days: best.d };
}
